public static String removeFirst(String str, char ch) {
    int i = str.indexOf(ch);
    if (i == -1) {
        return str;
    }
    return str.substring(0, i) + str.substring(i + 1);
}

public static boolean isAnagram(String s1, String s2) {
    if (s1.length() != s2.length()) {
        return false;
    }
    for (int i = 0; i < s1.length(); i++) {
        String shorter = removeFirst(s2, s1.charAt(i));
        if (shorter.length() == s2.length()) {
            return false;
        }
        s2 = shorter;
    }
    return true;
}

